 if(matches.some(([r])=>r==='snowtree'))return 'snowtree';if(matches.some(([r])=>r==='woodwall'))return 'woodwall';if(matches.some(([r])=>r==='campfire'))return 'campfire';if(matches.some(([r])=>r==='stump'))return 'stump';if(matches.some(([r])=>r==='log'))return 'log';
