function genContext(b,r){let idx=genIndex(),packs=new Map();let chosen=$('genPack')?.value;if(chosen)return {idx,pack:chosen};for(let role of genThemes[b].ground)for(let a of idx.get(role)||[]){if(!a.pack)continue;if(!packs.has(a.pack))packs.set(a.pack,new Set());packs.get(a.pack).add(role)}let candidates=[...packs.keys()];let ddCandidates=candidates.filter(p=>[...idx.values()].some(v=>v.some(a=>a.dd&&a.pack===p)));if(ddCandidates.length)candidates=ddCandidates;let pack=$('genLibraryMode').value==='theme'&&candidates.length?genPick(candidates,r):null;return {idx,pack};}
