function fillFxGlow(x,y,r,color,a){if(r<=0)return;let g=fc.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(${color},${a})`);g.addColorStop(1,`rgba(${color},0)`);fc.fillStyle=g;fc.fillRect(x-r,y-r,r*2,r*2);}
