function drawFx(now=performance.now()){if(!project||$('editor').hidden||!cw||!ch)return;if(fxCanvas.width!==canvas.width||fxCanvas.height!==canvas.height){fxCanvas.width=canvas.width;fxCanvas.height=canvas.height;}fc.setTransform(dpr,0,0,dpr,0,0);fc.clearRect(0,0,cw,ch);let m=map();if(!effectsOf().length)return;fc.save();fc.translate(ox,oy);fc.scale(zoom,zoom);fc.beginPath();fc.rect(0,0,m.w*S,m.h*S);fc.clip();if(testing&&testScope){fc.beginPath();for(let k of testScope){let [x,y]=k.split(',').map(Number);fc.rect(x*S,y*S,S,S)}fc.clip();}for(let f of effectsOf()){if(!fxVisible(f))continue;let key=fxKey(m,f),start=fxPlaying.get(key),elapsed=(now-(start??0))/1000,r=f.size*S/2,px=(f.x+.5)*S,py=(f.y+.5)*S;if(start!=null&&f.mode!=='loop'&&elapsed>=f.duration){fxPlaying.delete(key);start=undefined;}if(!fxStopped.has(key)&&(f.mode==='loop'||start!=null)&&ox+(px+r*1.5)*zoom>=0&&ox+(px-r*1.5)*zoom<=cw&&oy+(py+r*1.5)*zoom>=0&&oy+(py-r*1.5)*zoom<=ch){fc.save();fc.beginPath();fc.rect(px-r,py-r,r*2,r*2);fc.clip();paintFx(f,Math.max(0,elapsed),Math.max(0,Math.min(1,elapsed/f.duration)));fc.restore();}if(!testing&&tool==='effect'){fc.strokeStyle=f.id===fxSelected?'#ffe4a3':'#b8a6ef';fc.lineWidth=1.5/zoom;fc.setLineDash([4/zoom,4/zoom]);fc.strokeRect(px-r,py-r,r*2,r*2);fc.setLineDash([]);fc.fillStyle='#3e3159';fc.fillRect(px-9,py-9,18,18);fc.fillStyle='#fff0cf';fc.font='bold 12px system-ui';fc.textAlign='center';fc.textBaseline='middle';fc.fillText('✦',px,py);}}fc.restore();}
