function fxCovers(f,x,y){return Math.abs(f.x-x)<f.size/2+.5&&Math.abs(f.y-y)<f.size/2+.5;}
function triggerStepFx(x,y,previous=null){let m=map(),names=[],hidden=[];for(let f of effectsOf(m)){if(!fxCovers(f,x,y))continue;let linked=Object.values(eventsOf(m)).some(ev=>ev.effectId===f.id);if(f.mode!=='step'&&!(f.mode==='event'&&!linked))continue;if(!fxVisible(f)){hidden.push(f.name);continue;}let key=fxKey(m,f);if(previous&&fxCovers(f,previous.x,previous.y)&&fxPlaying.has(key))continue;fxStart(f,m);names.push(f.name)}if(names.length){status('Effekt ausgelöst: '+names.join(', '));drawFx();}else if(hidden.length){status('Effekt nicht sichtbar für Testspieler '+$('testPlayer').value+': '+hidden.join(', '));}return names.length;}
