const artAliases={grass:'grass|gras|lawn|turf',dirt:'dirt|earth|soil|erde|ground',sand:'sand|desert|wüste',snow:'snow|schnee',stone:'flagstone|stone floor|steinplatten|slate',wood:'wood floor|plank|holzdielen|wooden floor',cobble:'cobble|pflaster',water:'water|wasser',mud:'mud|schlamm',moss:'moss|moos',lava:'lava|magma',marble:'marble|marmor',tree:'tree|baum|oak',pine:'pine|fir|spruce|tanne',bush:'bush|shrub|busch',rock:'rock|boulder|felsen',flowers:'flower|blumen',stump:'stump|baumstumpf',reeds:'reed|schilf',cactus:'cactus|kaktus',snowtree:'snow tree|snowy fir|schneetanne|snow pine',log:'log|baumstamm|fallen tree',wall:'stone wall|brick wall|steinwand',woodwall:'wood wall|wooden wall|holzwand',door:'door|tür',stairs:'stair|treppe',pillar:'pillar|column|säule',fence:'fence|zaun',chest:'chest|truhe',table:'table|tisch',bed:'bed|bett',barrel:'barrel|fass',crate:'crate|kiste',rug:'rug|carpet|teppich',torch:'torch|fackel',bookshelf:'bookshelf|bookcase|bücherregal',chair:'chair|stuhl',campfire:'campfire|lagerfeuer',npc:'npc|human|villager|merchant',monster:'monster|creature|goblin',wolf:'wolf',skeleton:'skeleton|skelett',dragon:'dragon|drache',point:'point|marker|special',trap:'trap|falle',puzzle:'puzzle|rätsel',spawn:'spawn|startpunkt',fire:'fire|feuer',explosion:'explosion'};
function artName(a){return String(a.genName||a.name||'').toLowerCase().replace(/[_/\\-]+/g,' ').replace(/([a-z])([0-9])/g,'$1 $2')}
function artImages(){return Object.values(project?.assets||{}).filter(a=>a&&typeof a.src==='string'&&a.src.startsWith('data:image/'));}
