function updateArtCoverage(){updateArtSummary();$('artCoverage').textContent=$('artSummary').textContent+' · '+artImages().length+' importierte Bilder. Nicht zugeordnete Motive behalten vorerst ihre alte Darstellung.';}
function artSuggest(id){let a=baseAssets[id],re=new RegExp(artAliases[id]||id,'i');let arr=artImages().filter(b=>b.cat===a.cat&&re.test(artName(b)));if(id==='tree')arr=arr.filter(b=>!/snow|stump|fallen|log/i.test(artName(b)));if(id==='wood')arr=arr.filter(b=>!/wall|door/i.test(artName(b)));return arr.sort((x,y)=>Number(!!x.pixel)-Number(!!y.pixel)||artName(x).length-artName(y).length)[0];}
