// v0.6.3 – campaign-wide pack themes. Never change logical asset IDs or tile data.
const packExtraAliases={stone:'stone|rock floor|paving|stone tile|stein',wood:'wood|planks|holz',tree:'deciduous|birch|maple|oak|laubbau?m',pine:'conifer|evergreen|nadelbaum',bush:'foliage|hedge',rock:'stone|stein',flowers:'blossom',wall:'masonry|wall|mauer|brick',woodwall:'timber wall|woodwall',door:'gate|tor',stairs:'staircase|steps',pillar:'column|post',bookshelf:'book shelf|shelf',rug:'mat',campfire:'camp fire|bonfire',npc:'person|people|villager|merchant|innkeeper|human',monster:'enemy|beast|orc|goblin|slime',trap:'trapdoor|falltür',spawn:'start|spawn',point:'pin|point|interest',fire:'flame',explosion:'blast'};
function packText(a){let name=String(a.genName||a.name||'').split(/[\\/]/).pop().replace(/\.[^.]+$/,'');return name.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_\-]+/g,' ').toLowerCase();}
function packPath(a){return String(a.genName||'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_\\/\-]+/g,' ').toLowerCase();}
function packMatch(id,a,full=false){let txt=full?packPath(a):packText(a);let primary=artAliases[id]||id,extra=packExtraAliases[id]||'';let hit=(str)=>str&&new RegExp('(?:^|[^\\p{L}])(?:'+str+')(?:$|[^\\p{L}])','iu').test(txt);if(id==='tree'&&/snow|stump|fallen|pine|fir|log|winter/.test(txt))return 0;if(id==='wall'&&/wood|timber|door|gate/.test(txt))return 0;if(id==='wood'&&/wall|door|fence/.test(txt))return 0;if(id==='fire'&&/camp|bonfire/.test(txt))return 0;if(id==='stone'&&/wall|pillar|boulder/.test(txt))return 0;if(id==='rock'&&/floor|wall|tile/.test(txt))return 0;if(id==='dirt'&&/grass|sand|snow|water/.test(txt))return 0;return hit(primary)?(full?65:110):hit(extra)?(full?45:85):0;}
function packInferCat(path,fallback,source){if(fallback!=='Eigene')return fallback;let obj={genName:path},matches=Object.values(baseAssets).map(b=>[b,packMatch(b.id,obj)]).filter(p=>p[1]).sort((a,b)=>b[1]-a[1]);if(matches.length&&matches[0][0].cat!=='Marker'&&(!matches[1]||matches[0][1]>matches[1][1]||matches[0][0].cat===matches[1][0].cat))return matches[0][0].cat;let inferred=inferCat(path,fallback);if(inferred!=='Eigene')return inferred;let src=source?.[0]||'';if(/Roguelike Indoors/.test(src))return 'Einrichtung';if(/Roguelike Characters/.test(src))return 'Kreaturen';return 'Eigene';}
function applySkinPacks(names,approx=false,record=true){if(testing)return '';let imgs=artImages().filter(a=>names.includes(a.pack));if(!imgs.length)return 'Keine Bilder in diesen Paketen.';if(record)remember();project.skins??={};let previous=project.skinPackState||{},before={},mapped={},quality={};for(let [id,old] of Object.entries(previous.mapped||{})){if(project.skins[id]===old){let p=previous.before?.[id];if(p&&project.assets[p])project.skins[id]=p;else delete project.skins[id];}}let index=new Map();for(let a of imgs){let role=genRole(a);if(!role)continue;if(!index.has(role))index.set(role,[]);index.get(role).push(a)}for(let b of Object.values(baseAssets)){let list=index.get(b.id)||[];list.sort((a,c)=>Number(!!a.pixel)-Number(!!c.pixel)||a.name.localeCompare(c.name));if(!list.length)continue;before[b.id]=project.skins[b.id]||null;project.skins[b.id]=list[0].id;mapped[b.id]=list[0].id;quality[b.id]='Name';}project.skinPackState={packs:[...names],approx:false,strict:true,before,mapped,quality,previousPrefer:previous.packs?.length?previous.previousPrefer:!!project.preferImportedArt};project.preferImportedArt=true;imgCache.clear();let n=Object.keys(mapped).length;return `${n}/${Object.keys(baseAssets).length} Standards eindeutig ersetzt. Unklare Motive bleiben manuell verfügbar.`;}
function renderSkinPacks(){let names=[...new Set(artImages().map(a=>a.pack).filter(Boolean))],state=project.skinPackState||{},list=$('skinPackList');list.replaceChildren();for(let name of names){let label=document.createElement('label'),cb=document.createElement('input');cb.type='checkbox';cb.dataset.pack=name;cb.checked=state.packs?.includes(name)||false;label.append(cb,document.createTextNode(' '+name+' ('+artImages().filter(a=>a.pack===name).length+' Bilder)'));list.append(label);}if(!names.length)list.textContent='Noch keine Pakete importiert. Nutze den ZIP-Import.';$('skinPackApprox').checked=!!state.approx;$('skinPackApply').disabled=!names.length;$('skinPackReset').disabled=!state.packs?.length;let n=Object.keys(state.mapped||{}).filter(id=>project.skins?.[id]===state.mapped[id]).length;$('skinPackReport').textContent=state.packs?.length?`${n}/${Object.keys(baseAssets).length} Standards aus ${state.packs.length} aktiven Paketen. Nicht passende Motive bleiben erhalten.`:'';}
$('skinPackApply').onclick=()=>{let names=[...$('skinPackList').querySelectorAll('input:checked')].map(x=>x.dataset.pack);if(!names.length){$('skinPackReport').textContent='Bitte mindestens ein Paket auswählen.';return;}let msg=applySkinPacks(names,$('skinPackApprox').checked);refresh();renderArt();$('artFeedback').textContent=msg;status(msg);};
$('skinPackReset').onclick=()=>{let st=project.skinPackState;if(!st)return;remember();for(let [id,v] of Object.entries(st.mapped||{}))if(project.skins?.[id]===v){let prev=st.before?.[id];if(prev&&project.assets[prev])project.skins[id]=prev;else delete project.skins[id];}project.preferImportedArt=!!st.previousPrefer;delete project.skinPackState;imgCache.clear();refresh();renderArt();$('artFeedback').textContent='Paket-Ersatz zurückgesetzt. Importierte Bilder bleiben verfügbar.';};


// v0.6.5 – accessible, always reachable close controls.
(function installWindowControls(){
 const closeBtn=(label,fn)=>{const b=document.createElement('button');b.type='button';b.className='window-x';b.textContent='×';b.title=label;b.setAttribute('aria-label',label);b.addEventListener('click',fn);return b;};
 const routes={packDialog:'packClose',artDialog:'artClose',eventDialog:'evCancel',eventView:'eventViewClose',creatureDialog:'crCancel',creatureView:'crViewClose',fxDialog:'fxCancel'};
 for(const [id,action] of Object.entries(routes)){
  const d=$(id),heading=d.querySelector('h2');if(!heading)continue;
  let head=id==='packDialog'?heading.parentElement:document.createElement('div');
  if(id!=='packDialog'){heading.before(head);head.append(heading);}head.classList.add('dialog-window-head');
  if(id==='packDialog'){const b=$(action);b.textContent='×';b.classList.add('window-x');b.title='Fenster schließen';b.setAttribute('aria-label','Fenster schließen');}
  else head.append(closeBtn('Fenster schließen',()=>$(action).click()));
 }
 for(const p of document.querySelectorAll('.view .panel'))p.append(closeBtn('Zum Hauptmenü zurück',()=>p.querySelector('[data-open="home"]').click()));
 const bar=document.createElement('div');bar.className='window-switches';bar.setAttribute('aria-label','Werkzeugfenster');let lbl=document.createElement('span');lbl.textContent='Fenster:';bar.append(lbl);document.querySelector('.edcenter').prepend(bar);
 for(const [selector,name,title] of [['.edleft','Karten & Werkzeuge','Werkzeuge'],['.edright','Asset-Bibliothek','Assets']]){
  const side=document.querySelector(selector),head=document.createElement('div'),b=document.createElement('button');head.className='side-window-head';head.textContent=title;b.type='button';b.textContent=name;b.setAttribute('aria-pressed','true');bar.append(b);
  function setOpen(open){side.hidden=!open;b.setAttribute('aria-pressed',String(open));b.title=open?'Fenster ausblenden':'Fenster öffnen';requestAnimationFrame(()=>{if(!$('editor').hidden&&project)resizeCanvas();});}
  head.append(closeBtn(name+' schließen',()=>setOpen(false)));side.prepend(head);b.onclick=()=>setOpen(side.hidden);b.title='Fenster ausblenden';
 }
 for(const detail of document.querySelectorAll('#editor details.edsection')){const sum=detail.querySelector('summary');if(!sum)continue;const name=sum.textContent.trim();sum.append(closeBtn(name+' schließen',e=>{e.preventDefault();e.stopPropagation();detail.open=false;sum.focus();}));}
})();

// v0.6.5: persistent large campaign store; legacy localStorage remains readable.
function copyProject(p){const {assets,...rest}=p;return {...clone(rest),assets:Object.fromEntries(Object.entries(assets||{}).map(([id,a])=>[id,{...a}]))}}
let dbPromise;
function campaignDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{let r=indexedDB.open('DnDGameCreator',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('campaigns'))r.result.createObjectStore('campaigns',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Datenbank blockiert'))});return dbPromise}
async function dbWrite(w){let db=await campaignDB();return new Promise((resolve,reject)=>{let tx=db.transaction('campaigns','readwrite');tx.objectStore('campaigns').put(w);tx.oncomplete=()=>resolve();tx.onerror=tx.onabort=()=>reject(tx.error||Error('Speichern fehlgeschlagen'))})}
async function dbList(){let db=await campaignDB();return new Promise((resolve,reject)=>{let r=db.transaction('campaigns','readonly').objectStore('campaigns').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
const volatileWorlds=new Map();
renderSaved=async function(){let out=$('saved');out.textContent='Kampagnen werden geladen …';$('loadStatus').textContent='';let worlds=new Map(get('worlds',[]).map(w=>[w.id,w]));try{for(let w of await dbList())worlds.set(w.id,w)}catch(e){$('loadStatus').textContent='IndexedDB nicht verfügbar. Exportdateien können weiterhin geladen werden.'}for(let [id,w] of volatileWorlds)worlds.set(id,w);out.replaceChildren();if(!worlds.size){out.textContent='Noch keine gespeicherten Kampagnen.';return}for(let w of worlds.values()){let row=document.createElement('div');row.className='saveitem';let n=document.createElement('span');n.textContent=w.name+' · '+Object.keys(w.project.assets||{}).length+' Assets';row.append(n,btn('Öffnen',()=>initEditor(w)));out.append(row)}};
$('save').onclick=async()=>{if(testing||packBusy)return;let w=pack();if(!w.name){status('Bitte einen Kampagnennamen eingeben.');$('world').focus();return}let target=project;currentId=w.id;$('save').disabled=true;status('Kampagne wird gespeichert …');try{await dbWrite(w);volatileWorlds.delete(w.id);if(project===target){dirty=false;lastSavedName=w.name;status('Kampagne mit allen Assets gespeichert (IndexedDB).')}}catch(e){volatileWorlds.set(w.id,w);status('Dauerhaftes Speichern fehlgeschlagen: '+(e.message||e.name)+'. Bitte Kampagne exportieren!')}finally{$('save').disabled=testing}};

