function windowMapContext(){return ctx}
function ddType(path){return path.toLowerCase().split('/textures/')[1]?.split('/')[0]||''}
function ddName(path){return path.split('/').pop().replace(/\.[^.]+$/,'').replace(/_/g,' ').toLowerCase()}
function ddRole(path){let type=ddType(path),n=ddName(path);
 if(['terrain','patterns','tilesets'].includes(type)){
  if(/grass|lawn/.test(n))return 'grass';if(/cobble/.test(n))return 'cobble';if(/snow/.test(n))return 'snow';if(/sand/.test(n))return 'sand';if(/wood|plank/.test(n))return 'wood';if(/lava/.test(n))return 'lava';if(/water/.test(n))return 'water';if(/mud/.test(n))return 'mud';if(/moss/.test(n))return 'moss';if(/dirt|earth|soil/.test(n))return 'dirt';if(/stone|slate|cave floor|flagstone|rock ground/.test(n))return 'stone';return null;
 }
 if(type==='walls')return /wood/.test(n)&&!/stone/.test(n)?'woodwall':'wall';
 if(type==='portals')return /door|gate/.test(n)&&!/frame/.test(n)?'door':null;
 if(type!=='objects')return null;
 let roles=Object.entries(genRoleNames).filter(([r,re])=>!['grass','dirt','sand','snow','stone','wood','cobble','moss','mud','marble','water','lava'].includes(r)&&re.test(n));
 if(/tree/.test(n)&&!/fallen|stump|log/.test(n))return /snow/.test(n)?'snowtree':/pine|fir|spruce/.test(n)?'pine':'tree';
 if(/stump/.test(n))return 'stump';if(/fallen tree|\blog\b/.test(n))return 'log';
 return roles.length===1?roles[0][0]:null;
}
function ddCategory(path){let t=ddType(path),r=ddRole(path);if(['terrain','patterns','tilesets'].includes(t))return 'Böden';if(['walls','portals'].includes(t))return 'Gebäude';if(t==='paths')return 'Eigene';return baseAssets[r]?.cat||'Eigene'}
function ddSolid(path){return ['wall','woodwall','tree','pine','snowtree','rock','pillar','fence','water','lava'].includes(ddRole(path))}
function ddData(blob,name){const mime={png:'image/png',webp:'image/webp',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',bmp:'image/bmp',svg:'image/svg+xml',avif:'image/avif'}[name.split('.').pop().toLowerCase()];return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Bild nicht lesbar'));r.readAsDataURL(blob.slice(0,blob.size,mime||'application/octet-stream'))})}
function ddEntries(buf){let v=new DataView(buf),n=buf.byteLength;if(n<88||v.getUint32(0,true)!==0x43504447)throw Error('Keine gültige Dungeondraft-Datei');let ver=v.getUint32(4,true);if(ver!==0&&ver!==1)throw Error('Dieses Dungeondraft-Packformat wird noch nicht unterstützt (Version '+ver+')');let p=84,count=v.getUint32(p,true);p+=4;let entries=[],meta=[];const dec=new TextDecoder();for(let i=0;i<count;i++){if(p+4>n)throw Error('Unvollständiges Paketverzeichnis');let len=v.getUint32(p,true);p+=4;if(len>n-p-32)throw Error('Ungültiger Dateipfad');let name=dec.decode(new Uint8Array(buf,p,len)).replace(/\0+$/,'');p+=len;let offset=Number(v.getBigUint64(p,true)),size=Number(v.getBigUint64(p+8,true));p+=32;if(!Number.isSafeInteger(offset)||!Number.isSafeInteger(size)||offset<0||size>n-offset)throw Error('Ungültiger Dateibereich');let item={name,offset,size};if(/\/pack\.json$/i.test(name))meta.push(item);if(/\/textures\/(objects|terrain|patterns|tilesets|walls|portals|paths)\//i.test(name)&&supportedArt.test(name))entries.push(item)}let author='';try{if(meta.length){let m=meta[0];author=JSON.parse(dec.decode(new Uint8Array(buf,m.offset,m.size))).author||''}}catch{}return entries.map(e=>({name:e.name,dd:true,author,read:async()=>new Blob([new Uint8Array(buf,e.offset,e.size)])}))}
function updateDDPackOptions(){let el=$('genPack');if(!el)return;let names=[...new Set(Object.values(project.assets||{}).filter(a=>a.dd&&a.pack).map(a=>a.pack))],sig=JSON.stringify(names);if(el.dataset.sig===sig)return;let prev=el.value;el.replaceChildren(new Option('Automatisch (wie bisher)',''),...names.map(n=>new Option(n,n)));el.value=names.includes(prev)?prev:'';el.dataset.sig=sig}
const ddSelect=document.createElement('label');ddSelect.textContent='Bevorzugtes Dungeondraft-Set';const ddPicker=document.createElement('select');ddPicker.id='genPack';ddPicker.add(new Option('Automatisch (wie bisher)',''));ddSelect.append(ddPicker);$('genLibraryMode').parentElement.after(ddSelect);const ddHint=document.createElement('p');ddHint.className='hint';ddHint.textContent='Bei fehlenden Motiven verwendet der Generator weiterhin Standardgrafiken.';ddSelect.after(ddHint);


// v0.8.3: map-space HD textures, natural object size and optional blending.
function hdArt(id){return project?.assets?.[project.skins?.[id]]||asset(id)}
