 function selectTrack(t){let source=parse(t.url);if(!source)return;cleanup();active={...t,...source,trackId:t.id};$('musicCurrent').textContent=t.name;state('selected','Bereit – Play drücken.');renderList();}

 async function start(t){let source=parse(t.url);if(!source)return;cleanup();let ticket=seq;active={...t,...source,trackId:t.id};$('musicCurrent').textContent=t.name;state('loading','Wird geladen …');renderList();volume();audio.loop=$('musicLoop').checked;audio.src=source.url;timeout=setTimeout(()=>{if(ticket===seq&&phase==='loading')state('error','Audio lädt zu lange. Bitte eine andere Datei verwenden.')},12000);try{await audio.play();if(ticket===seq){clearTimeout(timeout);state('playing','Wird abgespielt')}}catch(e){if(ticket===seq)state('error','Audio konnte nicht gestartet werden. Bitte Dateiformat prüfen oder Play erneut anklicken.')}
 }
