 $('musicPause').onclick=()=>{if(!active)return;clearTimeout(timeout);audio.pause();state('paused','Pausiert')};$('musicStop').onclick=()=>stop();
 $('musicVolume').oninput=()=>{let n=Number(val('musicVolume'));$('volume').value=n;$('volume').dispatchEvent(new Event('input'));put('volume',n);volume()};$('musicLoop').onchange=()=>{put('musicLoop',$('musicLoop').checked);audio.loop=$('musicLoop').checked};$('volume').addEventListener('input',volume);
 function resetEdit(){edit=null;$('musicName').value='';$('musicNameLabel').hidden=true;$('musicAdd').hidden=true;$('musicFileOpen').hidden=false;$('musicScope').value='';$('musicAdd').textContent='Änderungen speichern';$('musicCancel').hidden=true}
 function scopes(){let s=$('musicScope'),old=s.value;s.replaceChildren(new Option('Ganze Kampagne',''),...project.maps.map(m=>new Option(m.name,m.id)));if([...s.options].some(o=>o.value===old))s.value=old;}
 function renderList(){if(!project)return;let out=$('musicList');out.replaceChildren();let ts=tracks().filter(t=>val('musicFilter')==='all'||!t.scope||t.scope===map().id);if(!ts.length)out.textContent='Noch keine Lieder in diesem Bereich.';for(let t of ts){let r=document.createElement('div');r.className='musicTrack'+(active?.trackId===t.id?' active':'');let b=document.createElement('button');b.type='button';b.className='trackTitle';b.textContent='▶ '+t.name;let s=document.createElement('small');s.textContent=label(t)+' · Audiodatei';b.append(s);b.onclick=()=>start(t);let e=document.createElement('button');e.type='button';e.textContent='✎';e.title='Bearbeiten';e.onclick=()=>{if(testing)return;edit=t.id;$('musicName').value=t.name;$('musicNameLabel').hidden=false;$('musicAdd').hidden=false;$('musicFileOpen').hidden=true;$('musicScope').value=t.scope||'';$('musicAdd').textContent='Änderungen speichern';$('musicCancel').hidden=false};let d=document.createElement('button');d.type='button';d.textContent='×';d.title='Lied entfernen';d.onclick=()=>{if(testing)return;if(active?.trackId===t.id)stop(true);remember();project.music=tracks().filter(x=>x.id!==t.id);if(edit===t.id)resetEdit();renderList()};e.disabled=d.disabled=testing;r.append(b,e,d);out.append(r)}$('musicAdd').disabled=$('musicFileOpen').disabled=testing;}
 $('musicAdd').onclick=()=>{if(!project||testing||!edit)return;let name=val('musicName').trim(),old=tracks().find(t=>t.id===edit);if(!name||!old){tell('Bitte einen Namen eingeben.');return}remember();let t={...old,name,scope:val('musicScope')};project.music=tracks().map(x=>x.id===edit?t:x);if(active?.trackId===t.id){active.name=name;active.scope=t.scope;$('musicCurrent').textContent=name;}resetEdit();renderList();tell('Änderungen gespeichert.');};$('musicFileOpen').onclick=()=>$('musicFile').click();$('musicFile').onchange=async()=>{if(!project||testing)return;const files=[...$('musicFile').files],target=project,scope=val('musicScope');$('musicFile').value='';let added=[];for(const f of files){let mime=f.type.startsWith('audio/')?f.type:({mp3:'audio/mpeg',ogg:'audio/ogg',wav:'audio/wav',m4a:'audio/mp4',flac:'audio/flac',aac:'audio/aac',opus:'audio/ogg'}[f.name.split('.').pop().toLowerCase()]);if(!mime)continue;try{let url=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(new Blob([f],{type:mime}))});if(project!==target||testing)return;added.push({id:idgen(),name:f.name.replace(/\.[^.]+$/,''),url,scope});}catch{}}if(!added.length){tell('Keine lesbaren Audiodateien ausgewählt.');return}if(project!==target||testing)return;remember();project.music=[...tracks(),...added];if(!active||phase==='selected'||phase==='idle'||phase==='stopped')selectTrack(added[0]);else renderList();tell(added.length+' Audiodatei(en) hinzugefügt – Play drücken.');};$('musicCancel').onclick=resetEdit;$('musicFilter').onchange=renderList;
 function place(x,y){position=[Math.max(6,Math.min(x,innerWidth-win.offsetWidth-6)),Math.max(6,Math.min(y,innerHeight-win.offsetHeight-6))];win.style.left=position[0]+'px';win.style.top=position[1]+'px'}
 function hide(){win.hidden=true;win.classList.remove('minimized');open.setAttribute('aria-expanded','false');$('musicClose').textContent='×';if(!$('editor').hidden)canvas.focus()}
