 function showMusic(){if(!project)return;win.hidden=false;win.classList.remove('minimized');open.setAttribute('aria-expanded','true');$('musicClose').textContent='×';$('musicClose').title='Schließen';scopes();renderList();let r=win.getBoundingClientRect();place(...(position||[r.left,r.top]))}
 open.onclick=()=>win.hidden||win.classList.contains('minimized')?showMusic():close();$('musicClose').onclick=()=>win.classList.contains('minimized')?showMusic():close();title.onpointerdown=e=>{if(e.button!==0||e.target.closest('button'))return;e.preventDefault();let r=win.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX-r.left,y:e.clientY-r.top};title.setPointerCapture(e.pointerId)};title.onpointermove=e=>{if(drag?.id===e.pointerId)place(e.clientX-drag.x,e.clientY-drag.y)};title.onpointerup=title.onpointercancel=title.onlostpointercapture=()=>{drag=null};window.addEventListener('resize',()=>{if(!win.hidden&&position)place(...position)});win.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}e.stopPropagation()});
 // Optional music-only network session; no gameplay data is transmitted.
 let shared=null, shareChain=Promise.resolve(), sentTrack=null;
 const shareStatus=msg=>$('musicShareStatus').textContent=msg;
 function publishMusic(p){if(!shared||!['playing','paused','stopped','idle','loading','error'].includes(p))return;
   const session=shared, track=active?.kind==='audio'?active:null;
   const mode=p==='playing'&&track?'playing':p==='paused'&&track?'paused':'stopped';
   const pos=mode==='stopped'?0:audio.currentTime||0, loop=$('musicLoop').checked;
   const desired=track?{id:track.trackId,name:track.name,url:track.url}:null;
   shareChain=shareChain.catch(()=>{}).then(async()=>{if(shared!==session)return;const payload={mode,pos,loop};
      if(mode!=='stopped'&&desired){payload.trackId=desired.id;if((!sentTrack||sentTrack.id!==desired.id||sentTrack.url!==desired.url||sentTrack.name!==desired.name))payload.track=desired;}
      const res=await fetch('/api/music/'+session.room+'/state',{method:'POST',headers:{'Content-Type':'application/json','X-DM-Key':session.key},body:JSON.stringify(payload)});
      if(!res.ok)throw Error(await res.text());if(shared!==session)return;if(payload.track)sentTrack=desired;shareStatus('Musiksession aktiv · '+(mode==='playing'?'Wiedergabe':mode==='paused'?'Pausiert':'Gestoppt'));
   }).catch(e=>{if(shared===session)shareStatus('Synchronisierung fehlgeschlagen: '+e.message)});
 }
 $('musicShare').onclick=async()=>{if(shared)return; $('musicShare').disabled=true;try{
    if(self!==top||!/^https?:$/.test(location.protocol))throw Error('Bitte das Spiel über den mitgelieferten Musikserver öffnen, nicht in der Vorschau.');
    const r=await fetch('/api/music',{method:'POST'});if(!r.ok)throw Error('Musikserver nicht verfügbar.');const data=await r.json();if(!data.room||!data.key)throw Error('Musikserver nicht verfügbar.');
    shared=data;sentTrack=null;$('musicShareLink').value=location.origin+'/listen/'+data.room;$('musicShareLink').hidden=false;$('musicShareEnd').hidden=false;shareStatus('Hör-Link an deine Spieler senden.');publishMusic(phase);
 }catch(e){shareStatus(e.message);$('musicShare').disabled=false;}};
 $('musicShareLink').onclick=()=> $('musicShareLink').select();
