 // Campaign switches stop playback; undo/redo replace the project object but not the campaign.
 const origInit=initEditor;initEditor=function(...args){endMusicShare();stop(true);hide();resetEdit();let result=origInit(...args);owner=project;if(Array.isArray(project?.music)){const n=project.music.length;project.music=tracks();if(project.music.length!==n){setDirty();status('Alte Musiklinks entfernt. Audiodateien bleiben erhalten.');}}return result};
