// v0.9.0 – campaign player slots; independent start positions and current locations.
let partySelected=1,partyGroup=new Set(),partyOwner=null,partyTestCurrent=false;
const partyImages=new Map();
const partyPanel=document.createElement('details');partyPanel.id='partyPanel';partyPanel.className='edsection';
partyPanel.innerHTML=`<summary>Spielerverwaltung</summary><p class="partyNote">Lokale Spielerplätze – noch keine verbundenen Spieler. Jeder Platz behält seine Nummer in dieser Kampagne.</p>
<div class="partyActions"><button type="button" id="partyAdd">+ Spielerplatz</button><button type="button" id="partyAll">Alle auswählen</button></div><div id="partyList"></div>
<div id="partyEdit" hidden><div class="partyHeading" id="partyNumber"></div><label>Charaktername<input id="partyName" maxlength="80"></label><div class="partyActions"><button type="button" id="partySaveName">Name übernehmen</button><button type="button" id="partyOwn">Eigenen Charakter nutzen</button></div><label>Charakterbild<input id="partyImage" type="file" accept="image/*"></label><div class="partyActions"><button type="button" id="partyClearImage">Bild entfernen</button><button type="button" id="partyRemove">Spieler entfernen</button></div>
<div class="partyHeading">Startpunkte & Positionen</div><div id="partyLocation" class="partyNote"></div><div class="partyActions"><button type="button" id="partySpawn">Startpunkt setzen</button><button type="button" id="partyMove">Spieler versetzen</button><button type="button" id="partyCancel">Platzierung beenden</button></div><div class="partyActions"><button type="button" id="partyEntry">Diese Karte als Startkarte</button><button type="button" id="partyClearSpawn">Startpunkt löschen</button></div><div class="partyActions"><button type="button" id="partyGo">Zur Spielerposition</button><button type="button" id="partyReset">Zurück zum Start</button></div><div class="partyHeading">Gruppenwechsel</div><p class="partyNote">Spieler oben anhaken, Zielkarte links öffnen, dann gemeinsam versetzen. Vorhandene Startpunkte werden bevorzugt.</p><button type="button" id="partyTransfer" class="wide">Ausgewählte auf diese Karte versetzen</button><div class="partyHeading">Testspieler</div><label><input type="checkbox" id="partyTestCurrent"> Von aktueller Position testen (sonst Startpunkt)</label><button type="button" id="partyTest" class="wide">Als diesen Spieler testen</button></div><p id="partyStatus" class="partyNote" role="status"></p>`;
document.querySelector('#editor .edleft').append(partyPanel);
function partyList(){return Array.isArray(project?.players)?project.players.filter(p=>p&&Number.isInteger(p.number)&&p.number>=1&&p.number<=32).sort((a,b)=>a.number-b.number):[]}
function partyBy(n){return partyList().find(p=>p.number===n)}
