// v0.9.1b – Web – local lobby and campaign launch, transport-independent lobby state.
(function(){
 const lobby=$('lobby'), board=$('lobbyBoard'), c=board.getContext('2d'), W=48,H=27,T=35;
 ids.push('lobby');let owner=null, members=new Map(), active=null, launched=false, busy=false, picture='',picSeq=0;
 const roster=()=>[...members.values()].sort((a,b)=>a.number-b.number);
 const msg=s=>$('lobbyStatus').textContent=s;
 const validPic=s=>/^data:image\/(png|jpeg|webp);base64,/.test(s||'');
 // Collision geometry is authored in the reference image's 1648 × 928 coordinate space.
 const floor=[[78,210],[410,190],[1090,190],[1160,190],[1160,220],[1335,220],[1370,240],[1370,330],[1505,405],[1570,410],[1570,770],[847,770],[847,843],[710,843],[710,770],[78,770]];
 const rect=(x,y,w,h)=>[[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
 const obstacles=[rect(77,170,205,85),[[410,165],[1021,165],[1021,300],[970,316],[490,316],[430,295],[410,257]],rect(515,263,54,72),rect(608,263,49,72),rect(699,263,50,72),rect(790,263,49,72),rect(880,263,50,72),rect(1073,165,108,40),rect(1190,166,132,47),rect(1340,254,66,73),[[203,268],[254,245],[340,249],[368,282],[365,374],[328,405],[227,400],[205,370]],rect(164,420,246,168),[[305,621],[345,594],[446,596],[475,634],[477,708],[452,758],[328,751],[299,708]],[[1023,350],[1070,332],[1160,333],[1190,360],[1185,459],[1150,493],[1050,490],[1020,445]],rect(1008,545,181,167),[[1300,605],[1340,578],[1427,574],[1462,617],[1468,692],[1437,747],[1324,745],[1297,690]],[[1314,345],[1360,341],[1402,377],[1398,421],[1361,437],[1311,403]],[[1392,405],[1441,399],[1450,444],[1403,456],[1392,440]],[[1449,422],[1505,410],[1540,447],[1516,500],[1470,487],[1445,463]]];
 function inside(x,y,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let [a,b]=poly[i],[u,v]=poly[j];if((b>y)!==(v>y)&&x<(u-a)*(y-b)/(v-b)+a)yes=!yes}return yes}
 function near(x,y,poly,r){return poly.some(([a,b],i)=>{let [u,v]=poly[(i+1)%poly.length],dx=u-a,dy=v-b,t=Math.max(0,Math.min(1,((x-a)*dx+(y-b)*dy)/(dx*dx+dy*dy)));return (x-a-t*dx)**2+(y-b-t*dy)**2<r*r})}
 const occupied=(x,y,n)=>roster().some(p=>p.number!==n&&p.x===x&&p.y===y);
 const cells=new Set();for(let y=0;y<H;y++)for(let x=0;x<W;x++){let a=(x+.5)*1648/W,b=(y+.5)*928/H;if(inside(a,b,floor)&&!near(a,b,floor,13)&&!obstacles.some(o=>inside(a,b,o)||near(a,b,o,13)))cells.add(x+','+y)}
 // Retain only the connected walkable area around the centre of the tavern.
 const reachable=new Set(),queue=[[21,14]];while(queue.length){let [x,y]=queue.pop(),k=x+','+y;if(reachable.has(k)||!cells.has(k))continue;reachable.add(k);queue.push([x+1,y],[x-1,y],[x,y+1],[x,y-1])}
 const walkable=(x,y)=>reachable.has(x+','+y);
 const spawnCells=[...reachable].map(k=>k.split(',').map(Number)).sort((a,b)=>(a[0]-21)**2+(a[1]-14)**2-(b[0]-21)**2-(b[1]-14)**2);
 const tavern=new Image();tavern.onload=()=>{if(!lobby.hidden)draw()};tavern.src='./assets/tavern.webp';
 const images=new Map();
 function imgFor(src){if(!validPic(src))return null;if(!images.has(src)){let i=new Image();i.onload=()=>{if(!lobby.hidden)draw()};i.src=src;images.set(src,i)}return images.get(src)}
 function draw(){c.clearRect(0,0,board.width,board.height);c.fillStyle='#211c18';c.fillRect(0,0,board.width,board.height);if(tavern.complete&&tavern.naturalWidth)c.drawImage(tavern,0,0,board.width,board.height);
 for(let p of roster()){let x=(p.x+.5)*T,y=(p.y+.5)*T,r=15,im=imgFor(partyBy(p.number)?.image);c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=p.number===active?'#8a65b0':'#4c7183';c.fill();if(im?.complete&&im.naturalWidth){c.save();c.clip();let f=2*r/Math.min(im.naturalWidth,im.naturalHeight);c.drawImage(im,x-im.naturalWidth*f/2,y-im.naturalHeight*f/2,im.naturalWidth*f,im.naturalHeight*f);c.restore()}else{c.fillStyle='#fff';c.font='bold 19px system-ui';c.textAlign='center';c.textBaseline='middle';c.fillText(p.number,x,y)}c.strokeStyle=p.number===active?'#ffdb92':p.ready?'#a5e0bf':'#d6d0c5';c.lineWidth=3;c.stroke();c.font='bold 20px system-ui';c.textAlign='center';c.textBaseline='top';let name=(partyBy(p.number)?.name||'Spieler '+p.number).slice(0,24);c.strokeStyle='#211b17';c.lineWidth=3;c.strokeText(name,x,y+r+2);c.fillStyle='#fff';c.fillText(name,x,y+r+2);c.restore()}
 }
 function select(n){active=n;let p=partyBy(n);if(p){$('lobbyName').value=p.name||'';picture=p.image||'';picSeq++;$('lobbyImage').value='';showPic()}render()}
 function showPic(){let im=$('lobbyPortrait');im.hidden=!validPic(picture);if(!im.hidden)im.src=picture;else im.removeAttribute('src')}
 function render(){if(!project)return;$('lobbyCampaign').textContent=$('world').value.trim()||'Unbenannte Kampagne';$('lobbyCount').textContent=roster().filter(p=>p.ready).length+' / '+members.size+' bereit';let out=$('lobbyRoster');out.replaceChildren();for(let m of roster()){let p=partyBy(m.number);if(!p)continue;let b=document.createElement('button');b.type='button';b.className='lobbyMember'+(m.number===active?' chosen':'');let av=document.createElement('span');av.className='lobbyAvatar';if(validPic(p.image)){let im=new Image();im.src=p.image;im.alt='';av.append(im)}else av.textContent=p.number;let text=document.createElement('span');text.textContent='Spieler '+p.number+' · '+p.name;let sub=document.createElement('small');sub.textContent=(m.ready?'✓ Bereit':'○ Wartet')+' · '+(partyStart(p)?partyFormat(partyStart(p)):'Automatischer Startpunkt');text.append(sub);b.append(av,text);b.onclick=()=>{select(m.number);board.focus()};out.append(b)}if(!members.size)out.textContent='Noch keine Teilnehmer im Warteraum.';let available=partyList().filter(p=>!members.has(p.number));$('lobbyExisting').replaceChildren(new Option('Vorbereiteten Spielerplatz wählen',''),...available.map(p=>new Option(p.number+' · '+p.name,p.number)));$('lobbyExisting').disabled=!available.length;$('lobbyUseSlot').disabled=!available.length;$('lobbyNew').disabled=partyList().length>=32;$('lobbyEdit').hidden=!members.has(active);$('lobbyReady').textContent=members.get(active)?.ready?'Bereitschaft zurücknehmen':'✓ Bereit';$('lobbyStart').disabled=!members.size||!roster().every(p=>p.ready)||busy;$('lobbyStart').textContent='▶ Spiel starten (lokaler Test)';draw()}
 function join(n){let p=partyBy(n);if(!p||members.has(n))return;let cell=spawnCells.find(([x,y])=>!occupied(x,y,n));let spot=cell&&{x:cell[0],y:cell[1]};if(!spot){msg('Warteraum voll.');return}members.set(n,{number:n,...spot,ready:false});select(n);board.focus();msg('Spieler '+n+' ist dem lokalen Warteraum beigetreten.')}
 function open(){if(!project)return;if(testing)testToggle();if(owner!==project){owner=project;members.clear();active=null;launched=false;picture='';images.clear()}for(let n of members.keys())if(!partyBy(n))members.delete(n);if(!members.has(active))active=roster()[0]?.number??null;show('lobby');if(active!==null)select(active);else{ $('lobbyName').value='';picture='';showPic();render()}msg(launched?'Lokale Testlobby – erneut startbereit machen oder zum Editor zurück.':'Lokaler Test: Teilnehmer hinzufügen und bereit markieren.');board.focus()}
 $('lobbyOpen').onclick=open;$('lobbyDemo').onclick=()=>{initEditor({name:'Lobby-Test'});open()};$('lobbyBack').onclick=()=>{show('editor');refresh();requestAnimationFrame(fit)};
 $('lobbyUseSlot').onclick=()=>join(+$('lobbyExisting').value);$('lobbyNew').onclick=()=>{let n=Array.from({length:32},(_,i)=>i+1).find(n=>!partyBy(n));if(!n)return;remember();project.players=[...partyList(),{number:n,name:'Spieler '+n,image:'',spawns:{},entryMap:null,position:null}];refresh();join(n)};
 $('lobbyOwn').onclick=()=>{let v=get('character',{});if(!v.name){msg('Noch kein eigener Charakter im Hauptmenü gespeichert.');return}$('lobbyName').value=v.name;picture=v.image||'';picSeq++;showPic();msg('Profil übernommen – Änderungen speichern.')};
 $('lobbyImage').onchange=()=>{let f=$('lobbyImage').files[0],n=active,seq=++picSeq;if(!f)return;let u=URL.createObjectURL(f),im=new Image();im.onload=()=>{URL.revokeObjectURL(u);if(seq!==picSeq||n!==active)return;let cv=document.createElement('canvas'),scale=Math.min(1,512/Math.max(im.width,im.height));cv.width=Math.max(1,Math.round(im.width*scale));cv.height=Math.max(1,Math.round(im.height*scale));cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);picture=cv.toDataURL('image/png');showPic();msg('Bild ausgewählt – Änderungen speichern.')};im.onerror=()=>{URL.revokeObjectURL(u);msg('Bild konnte nicht gelesen werden.')};im.src=u};
 $('lobbyClearPic').onclick=()=>{picSeq++;picture='';$('lobbyImage').value='';showPic()};
 $('lobbySaveProfile').onclick=()=>{let p=partyBy(active),n=$('lobbyName').value.trim();if(!p||!n){msg('Bitte einen Charakternamen eingeben.');return}remember();p.name=n;p.image=validPic(picture)?picture:'';members.get(active).ready=false;refresh();render();msg('Charakterprofil gespeichert.');board.focus()};
 $('lobbyReady').onclick=()=>{let m=members.get(active);if(m){m.ready=!m.ready;render();board.focus()}};$('lobbyLeave').onclick=()=>{members.delete(active);active=roster()[0]?.number??null;if(active!==null)select(active);else render();msg('Spieler hat den Warteraum verlassen. Sein Kampagnenplatz bleibt erhalten.')};
 function step(dx,dy){let p=members.get(active);if(!p)return;let x=p.x+dx,y=p.y+dy;if(walkable(x,y)&&!occupied(x,y,active)){p.x=x;p.y=y;draw()}}for(let b of lobby.querySelectorAll('[data-lobby-step]'))b.onclick=()=>{step(...b.dataset.lobbyStep.split(',').map(Number));board.focus()};
 document.addEventListener('keydown',e=>{if(lobby.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();$('lobbyBack').click();return}if(e.target.closest('input,textarea,select,button')&&e.target!==board)return;let d={w:[0,-1],a:[-1,0],s:[0,1],d:[1,0],arrowup:[0,-1],arrowdown:[0,1],arrowleft:[-1,0],arrowright:[1,0]}[e.key.toLowerCase()];if(d){e.preventDefault();e.stopImmediatePropagation();step(...d)}},true);
 // Reserve every configured valid start before allocating fallback positions. No partial launch on failure.
 function plan(){let ps=roster().map(m=>partyBy(m.number)),ns=new Set(ps.map(p=>p.number)),reserved=new Set(partyList().filter(p=>!ns.has(p.number)).map(partyPosition).filter(Boolean).map(v=>v.mapId+':'+v.x+','+v.y)),planned=new Map(),old=mapId;let key=v=>v.mapId+':'+v.x+','+v.y;let free=v=>{mapId=v.mapId;if(roomCache?.map!==map())scanRooms();return !reserved.has(key(v))&&!blocked(v.x,v.y)};try{for(let p of ps){let v=partyStart(p);if(v&&free(v)){planned.set(p.number,{...v});reserved.add(key(v))}}for(let p of ps){if(planned.has(p.number))continue;let m=project.maps.find(m=>m.id===partyStart(p)?.mapId)||project.maps[0],v=null;mapId=m.id;scanRooms();for(let y=0;y<m.h&&!v;y++)for(let x=0;x<m.w&&!v;x++){let q={mapId:m.id,x,y};if(free(q))v=q}if(!v)return null;planned.set(p.number,v);reserved.add(key(v))}return planned}finally{mapId=old;scanRooms()}}
 $('lobbyStart').onclick=()=>{if(busy||!members.size||!roster().every(p=>p.ready))return;busy=true;try{let locations=plan();if(!locations){msg('Nicht genügend freie Startfelder. Bitte Startkarte und Hindernisse im Editor prüfen.');return}remember();for(let [n,v] of locations)partyBy(n).position=v;let n=members.has(active)?active:roster()[0].number;launched=true;for(let m of roster())m.ready=false;show('editor');refresh();partyTestCurrent=true;$('partyTestCurrent').checked=true;$('testPlayer').value=String(n);$('testPlayer').dispatchEvent(new Event('change'));testToggle();requestAnimationFrame(()=>{fit();followToken();canvas.focus()});status('Lokaler Lobby-Start: Spieler '+n+' · '+partyBy(n).name)}finally{busy=false}};
})();

